function render(){const c=state.class;$('#heroName').textContent=state.name;$('#className').textContent=`${c} of Ironvale`;$('#classTag').textContent=c.toUpperCase();$('#avatar').textContent=c==='Knight'?'♞':c==='Ranger'?'♧':'✧';$('#levelText').textContent=`LEVEL ${state.level}`;$('#hpText').textContent=`${state.hp} / ${state.maxHp}`;$('#hpMeter').style.width=`${state.hp/state.maxHp*100}%`;$(`#hpMeter`).parentElement.style.opacity=state.hp<30?'.8':'1';$('#xpText').textContent=`${state.xp} / ${state.xpNext} XP`;$('#xpMeter').style.width=`${state.xp/state.xpNext*100}%`;
// Gear contributes the best bonus found; displayed stats remain readable.
$('#powerStat').textContent=state.power+gearPower();$('#defenseStat').textContent=state.defense+gearGuard();$('#renownStat').textContent=state.renown;$('#goldTop').textContent=state.gold;$('#repTop').textContent=state.renown;$('#dayTop').textContent=`DAY ${state.day}`;$('#potionCount').textContent='×'+state.potions;$('#rankLabel').textContent=state.king?'SOVEREIGN':state.renown>=70?'LORD COMMANDER':state.renown>=30?'ROYAL CHAMPION':'SWORN KNIGHT';$('#rankDescription').textContent=state.king?'The crown rests upon your brow. Rule with courage, and keep the realm safe.':state.renown>=70?'The court whispers of a crown. Reach level 10, defeat every guardian, claim all quests, build a Stone Keep, and earn 250 renown.':'Defend the realm and earn the trust of its people. Slay the beasts that haunt the frontier.';$('#kingProgress').textContent=`${Math.min(250,state.renown)} / 250`;$('#kingMeter').style.width=`${Math.min(100,state.renown/250*100)}%`;$('#combatHint').textContent=state.foe?`Lv ${state.foe.level} ${state.foe.name} · ${Math.ceil(state.foe.hp)} HP`:'No foe in reach';renderTab();['frost','ember','capital'].forEach(id=>$(`[data-region="${id}"]`).classList.toggle('locked',!!regionRequirement(id)));}
$$('.tabrow button').forEach(b=>b.onclick=()=>{$$('.tabrow button').forEach(x=>x.classList.toggle('active',x===b));state.activeTab=b.dataset.tab;renderTab()});$$('.region-btn').forEach(b=>b.onclick=()=>unlockRegion(b.dataset.region));$('#attackBtn').onclick=attack;$('#interactBtn').onclick=interact;$('#restBtn').onclick=rest;$('#potionBtn').onclick=()=>{if(!state.potions){toast('No potions left.');return}if(state.hp===state.maxHp){toast('You are already at full health.');return}state.potions--;state.hp=Math.min(state.maxHp,state.hp+45);addLog('Used a healing draught.');toast('Recovered 45 vitality.');render()};$('#mapBtn').onclick=()=>showMap();$('#merchantBtn').onclick=openMerchant;$('#questsBtn').onclick=openQuests;$('#attackQuick').onclick=attack;$('#skillsQuick').onclick=()=>{state.activeTab='skills';renderTab()};$('#packQuick').onclick=()=>{state.activeTab='pack';renderTab()};$('#holdingsQuick').onclick=()=>{state.activeTab='holdings';renderTab()};
function openMerchant(){const stock=[{id:'potion',name:'Healing draught',desc:'Restore up to 45 vitality',cost:35,level:1},{id:'steel',name:'Steel longsword',desc:'+5 power · level 4',cost:190,level:4},{id:'frost',name:'Frostguard mail',desc:'+4 guard · level 6',cost:260,level:6},{id:'dragon',name:'Drakebone greatblade',desc:'+8 power · level 9',cost:520,level:9}];openModal(`<button class="close" onclick="closeModal()">✕</button><h2>TRAVELING MERCHANT</h2><p>Hard-won gear and field supplies. Better stock requires experience.</p><div class="choices">${stock.map(i=>`<div class="choice"><strong>${i.name} · ${i.cost} ◈</strong><span>${i.desc}</span><button class="smallbtn" onclick="purchase('${i.id}')" ${state.gold<i.cost||state.level<i.level?'disabled':''}>${state.level<i.level?'LEVEL '+i.level:'BUY'}</button></div>`).join('')}</div>`)}window.purchase=id=>{const stock={potion:{cost:35},steel:{cost:190,item:{name:'Steel longsword',rarity:'Rare',type:'weapon',power:5}},frost:{cost:260,item:{name:'Frostguard mail',rarity:'Rare',type:'armor',defense:4}},dragon:{cost:520,item:{name:'Drakebone greatblade',rarity:'Epic',type:'weapon',power:8}}},i=stock[id];if(!i||state.gold<i.cost)return;if(id==='steel'&&state.level<4||id==='frost'&&state.level<6||id==='dragon'&&state.level<9){toast('You are not experienced enough for that item.');return}state.gold-=i.cost;if(id==='potion')state.potions++;else state.inventory.push(i.item);addLog(`Bought ${id==='potion'?'a healing draught':i.item.name} from the traveling merchant.`);toast('Purchase complete.');openMerchant();render()};function openQuests(){const data=[['trail','Roadside Relief','Defeat 3 enemies',45,8],['guardian','Guardian Bounty','Defeat a regional guardian',100,15],['champion','Realm Champion','Defeat all 3 regional guardians',220,25]],html=data.map(([id,name,goal,gold,renown])=>{const q=state.quests[id],target=id==='trail'?3:id==='guardian'?1:3;return `<div class="property"><div><b>${name}</b><div class="sub">${q.claimed?'Reward claimed':q.done?`Complete · reward ${gold} crowns, ${renown} renown`:`${goal} · ${Math.min(q.progress,target)} / ${target}`}</div></div><button class="smallbtn" onclick="claimQuest('${id}')" ${!q.done||q.claimed?'disabled':''}>${q.claimed?'DONE':q.done?'CLAIM':'TRACKED'}</button></div>`}).join('');openModal(`<button class="close" onclick="closeModal()">✕</button><h2>ROYAL QUESTS</h2><p>Prove your worth across the frontier. Every reward must be claimed before the throne will recognize you.</p>${html}`)}window.claimQuest=id=>{const rewards={trail:{gold:45,renown:8},guardian:{gold:100,renown:15},champion:{gold:220,renown:25,potions:2}},q=state.quests[id],r=rewards[id];if(!q||!q.done||q.claimed)return;q.claimed=true;state.gold+=r.gold;state.renown+=r.renown;state.potions+=r.potions||0;addLog(`Claimed ${id} quest reward: +${r.gold} crowns, +${r.renown} renown.`);toast('Quest reward claimed.');openQuests();render()};function showMap(){openModal(`<button class="close" onclick="closeModal()">✕</button><h2>THE REALMS OF IRONVALE</h2><p>Defeat two foes to draw out a guardian. Guardians and level requirements open the road ahead.</p><div class="choices">${Object.entries(regions).map(([id,r])=>{const req=regionRequirement(id);const status=req?`LOCKED · ${req.replace(/\.$/,'')}`:id==='woods'?'OPEN TRAIL':id==='capital'?'ROYAL DISTRICT · Throne requires 250 renown, Stone Keep & all quests':`Guardian ${state.bossKills[id]?'defeated':'unfound'} · ${state.progress[id]} foes`;return `<button class="choice" onclick="travel('${id}')"><strong>${r.icon} ${r.name} · ${r.range}</strong><span>${status}</span></button>`}).join('')}</div>`)}
window.travel=id=>{closeModal();unlockRegion(id)};window.closeModal=()=>$('#modalBg').classList.remove('open');function openModal(html){$('#modal').innerHTML=html;$('#modalBg').classList.add('open')}
function chooseClass(){openModal(`<h2>THE ROAD BEGINS</h2><p>The king’s roads are unsafe, the old dragons stir, and the crown has no heir. Choose the calling that will shape your legend. You can still master every skill as you grow.</p><div class="choices"><button class="choice" onclick="pickClass('Knight')"><strong>♞ Knight</strong><span>Balanced defender · +4 guard, +15 vitality</span></button><button class="choice" onclick="pickClass('Ranger')"><strong>♧ Ranger</strong><span>Trail hunter · +3 power, better finds</span></button><button class="choice" onclick="pickClass('Arcanist')"><strong>✧ Arcanist</strong><span>Arcane blade · +5 power, +1 guard</span></button></div>`)}
window.pickClass=c=>{state.class=c;if(c==='Knight'){state.defense+=4;state.maxHp+=15;state.hp=state.maxHp}if(c==='Ranger'){state.power+=3;state.skills.scout=1}if(c==='Arcanist'){state.power+=5;state.defense++}closeModal();addLog(`You take the path of the ${c}.`);toast(`${c} chosen. The realm awaits!`);render()};
$('#modalBg').onclick=e=>{if(e.target.id==='modalBg')closeModal()};document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key===' '){attack();return}if(e.key.toLowerCase()==='e'){interact();return}if(e.key.toLowerCase()==='r'){rest();return}state.keys[e.key.toLowerCase()]=true});document.addEventListener('keyup',e=>state.keys[e.key.toLowerCase()]=false);$$('.touchpad button').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();move(b.dataset.dir,.18)})});
function move(dir,amt=.14){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];state.x=Math.max(35,Math.min(445,state.x+d[0]*amt*100));state.y=Math.max(140,Math.min(220,state.y+d[1]*amt*75));state.dir=d[0]||state.dir}

