 const skillDefs=[{id:'heavy',name:'Heavy Strike',desc:'+3 power per rank · cost 1 point',max:3},{id:'fortify',name:'Fortified',desc:'+2 guard per rank · cost 1 point',max:3},{id:'vital',name:'Vitality',desc:'+15 max health per rank · cost 1 point',max:3},{id:'scout',name:'Trailblazer',desc:'More crowns and better loot · cost 1 point',max:2}];
