ow.sellItem=index=>{sellItem(index);openMerchant()};window.purchase=id=>{const stock={potion:{cost:35},steel:{cost:190,level:4,item:{name:'Steel longsword',rarity:'Rare',type:'weapon',power:5,value:95}},frost:{cost:260,level:6,item:{name:'Frostguard mail',rarity:'Rare',type:'armor',defense:4,value:130}},dragon:{cost:520,level:9,item:{name:'Drakebone greatblade',rarity:'Epic',type:'weapon',power:8,value:260}},might:{cost:145,level:3},ward:{cost:145,level:3},pony:{cost:120,level:1},stag:{cost:280,level:5}},i=stock[id];if(!i||state.gold<i.cost)return;if(state.level<(i.level||1)){toast(`Requires level ${i.level}.`);return}if((id==='pony'||id==='stag')&&state.mount){toast('You already own a mount.');return}state.gold-=i.cost;if(id==='potion')state.potions++;else if(id==='might')state.power+=3;else if(id==='ward')state.defense+=3;else if(id==='pony'||id==='stag')state.mount=id==='pony'?'Trail Pony':'Frost Stag';else state.inventory.push(i.item);addLog(`Purchased ${id==='potion'?'a healing draught':id==='might'?'a Tome of Might':id==='ward'?'a Tome of Warding':id==='pony'?'a Trail Pony':id==='stag'?'a Frost Stag':i.item.name}.`);toast('Purchase complete.');openMerchant();render()};function openQuests(){const data=[['trail','Roadside Relief','Defeat 3 enemies',45,8],['guardian','Guardian Bounty','Defeat a regional guardian',100,15],['champion','Realm Champion','Defeat all 3 regional guardians',220,25]],html=data.map(([id,name,goal,gold,renown])=>{const q=state.quests[id],target=id==='trail'?3:id==='guardian'?1:3;return `<div class="property"><div><b>${name}</b><div class="sub">${q.claimed?'Reward claimed':q.done?`Complete · reward ${gold} crowns, ${renown} renown`:`${goal} · ${Math.min(q.progress,target)} / ${target}`}</div></div><button class="smallbtn" onclick="claimQuest('${id}')" ${!q.done||q.claimed?'disabled':''}>${q.claimed?'DONE':q.done?'CLAIM':'TRACKED'}</button></div>`}).join('');openModal(`<button class="close" onclick="closeModal()">✕</button><h2>ROYAL QUESTS</h2><p>Prove your worth across the frontier. Every reward must be claimed before the throne will recognize you.</p>${html}`)}window.claimQuest=id=>{const rewards={trail:{gold:45,renown:8},guardian:{gold:100,renown:15},champion:{gold:220,renown:25,potions:2}},q=state.quests[id],r=rewards[id];if(!q||!q.done||q.claimed)return;q.claimed=true;state.gold+=r.gold;state.renown+=r.renown;state.potions+=r.potions||0;addLog(`Claimed ${id} quest reward: +${r.gold} crowns, +${r.renown} renown.`);toast('Quest reward claimed.');openQuests();render()};function showMap(){openModal(`<button class="close" onclick="closeModal()">✕</button><h2>THE REALMS OF IRONVALE</h2><p>Defeat two foes to draw out a guardian. Guardians and level requirements open the road ahead.</p><div class="choices">${Object.entries(regions).map(([id,r])=>{const req=regionRequirement(id);const status=req?`LOCKED · ${req.replace(/\.$/,'')}`:id==='woods'?'OPEN TRAIL':id==='capital'?'ROYAL DISTRICT · Throne requires 250 renown, Stone Keep & all quests':`Guardian ${state.bossKills[id]?'defeated':'unfound'} · ${state.progress[id]} foes`;return `<button class="choice" onclick="travel('${id}')"><strong>${r.icon} ${r.name} · ${r.range}</strong><span>${status}</span></button>`}).join('')}</div>`)}
 window.travel=id=>{closeModal();unlockRegion(id)};window.closeModal=()=>$('#modalBg').classList.remove('open');function openModal(html){$('#modal').innerHTML=html;$('#modalBg').classList.add('open')}
 function chooseClass(){openModal(`<h2>THE ROAD BEGINS</h2><p>The king’s roads are unsafe, the old dragons stir, and the crown has no heir. Choose the calling that will shape your legend. You can still master every skill as you grow.</p><div class="choices"><button class="choice" onclick="pickClass('Knight')"><strong>♞ Knight</strong><span>Balanced defender · +4 guard, +15 vitality</span></button><button class="choice" onclick="pickClass('Ranger')"><strong>♧ Ranger</strong><span>Trail hunter · +3 power, better finds</span></button><button class="choice" onclick="pickClass('Arcanist')"><strong>✧ Arcanist</strong><span>Arcane blade · +5 power, +1 guard</span></button></div>`)}
